                if p == '?':
                    if c not in good_letters:
                        match = False
                        break
                else:
                    if c != p:
                        match = False
                        break
            print('YES' if match else 'NO')
    else:
        prefix = pattern[:star_pos]
        suffix = pattern[star_pos+1:]
        for q in queries:
            if len(q) < len(prefix) + len(suffix):
                print('NO')
                continue
            # Check prefix
            prefix_match = True
            for c, p in zip(q[:len(prefix)], prefix):
                if p == '?':
                    if c not in good_letters:
                        prefix_match = False
                        break
                else:
                    if c != p:
                        prefix_match = False
                        break
            if not prefix_match:
                print('NO')
                continue
