            suffix_match = True
            suffix_start = len(q) - len(suffix)
            for c, p in zip(q[suffix_start:], suffix):
                if p == '?':
                    if c not in good_letters:
                        suffix_match = False
                        break
                else:
                    if c != p:
                        suffix_match = False
                        break
            if not suffix_match:
                print('NO')
                continue
            # Check middle part (must be all bad letters)
            middle = q[len(prefix):suffix_start]
            middle_match = all(c not in good_letters for c in middle)
            print('YES' if middle_match else 'NO')

